-- PostgreSQL equivalents of the application's tenant integrity triggers.
CREATE OR REPLACE FUNCTION public.cbeos_guard_installations() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $cbeos$ BEGIN IF (NEW.supplier_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM suppliers WHERE id=NEW.supplier_id AND tenant_id=NEW.tenant_id)) THEN RAISE EXCEPTION 'tenant relationship mismatch'; END IF; RETURN NEW; END $cbeos$;
DROP TRIGGER IF EXISTS trg_installations_tenant_guard ON public.installations;
CREATE TRIGGER trg_installations_tenant_guard BEFORE INSERT OR UPDATE ON public.installations FOR EACH ROW EXECUTE FUNCTION public.cbeos_guard_installations();
CREATE OR REPLACE FUNCTION public.cbeos_guard_imports() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $cbeos$ BEGIN IF (NOT EXISTS (SELECT 1 FROM cases WHERE id=NEW.case_id AND tenant_id=NEW.tenant_id)) THEN RAISE EXCEPTION 'tenant relationship mismatch'; END IF; RETURN NEW; END $cbeos$;
DROP TRIGGER IF EXISTS trg_imports_tenant_guard ON public.imports;
CREATE TRIGGER trg_imports_tenant_guard BEFORE INSERT OR UPDATE ON public.imports FOR EACH ROW EXECUTE FUNCTION public.cbeos_guard_imports();
CREATE OR REPLACE FUNCTION public.cbeos_guard_import_lines() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $cbeos$ BEGIN IF (NOT EXISTS (SELECT 1 FROM cases WHERE id=NEW.case_id AND tenant_id=NEW.tenant_id) OR (NEW.import_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM imports WHERE id=NEW.import_id AND tenant_id=NEW.tenant_id AND case_id=NEW.case_id)) OR (NEW.product_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM products WHERE id=NEW.product_id AND tenant_id=NEW.tenant_id)) OR (NEW.supplier_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM suppliers WHERE id=NEW.supplier_id AND tenant_id=NEW.tenant_id)) OR (NEW.installation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM installations WHERE id=NEW.installation_id AND tenant_id=NEW.tenant_id AND (NEW.supplier_id IS NULL OR supplier_id IS NULL OR supplier_id=NEW.supplier_id))) OR (NEW.reporting_period_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM reporting_periods WHERE id=NEW.reporting_period_id AND tenant_id=NEW.tenant_id))) THEN RAISE EXCEPTION 'tenant relationship mismatch'; END IF; RETURN NEW; END $cbeos$;
DROP TRIGGER IF EXISTS trg_import_lines_tenant_guard ON public.import_lines;
CREATE TRIGGER trg_import_lines_tenant_guard BEFORE INSERT OR UPDATE ON public.import_lines FOR EACH ROW EXECUTE FUNCTION public.cbeos_guard_import_lines();
CREATE OR REPLACE FUNCTION public.cbeos_guard_documents() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $cbeos$ BEGIN IF (NOT EXISTS (SELECT 1 FROM cases WHERE id=NEW.case_id AND tenant_id=NEW.tenant_id) OR (NEW.import_line_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM import_lines WHERE id=NEW.import_line_id AND tenant_id=NEW.tenant_id AND case_id=NEW.case_id)) OR (NEW.supplier_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM suppliers WHERE id=NEW.supplier_id AND tenant_id=NEW.tenant_id)) OR (NEW.installation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM installations WHERE id=NEW.installation_id AND tenant_id=NEW.tenant_id AND (NEW.supplier_id IS NULL OR supplier_id IS NULL OR supplier_id=NEW.supplier_id))) OR (NEW.uploaded_by IS NOT NULL AND NOT EXISTS (SELECT 1 FROM users WHERE id=NEW.uploaded_by AND tenant_id=NEW.tenant_id))) THEN RAISE EXCEPTION 'tenant relationship mismatch'; END IF; RETURN NEW; END $cbeos$;
DROP TRIGGER IF EXISTS trg_documents_tenant_guard ON public.documents;
CREATE TRIGGER trg_documents_tenant_guard BEFORE INSERT OR UPDATE ON public.documents FOR EACH ROW EXECUTE FUNCTION public.cbeos_guard_documents();
CREATE OR REPLACE FUNCTION public.cbeos_guard_facts() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $cbeos$ BEGIN IF (NOT EXISTS (SELECT 1 FROM cases WHERE id=NEW.case_id AND tenant_id=NEW.tenant_id) OR NOT EXISTS (SELECT 1 FROM documents WHERE id=NEW.document_id AND tenant_id=NEW.tenant_id AND case_id=NEW.case_id) OR (NEW.import_line_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM import_lines WHERE id=NEW.import_line_id AND tenant_id=NEW.tenant_id AND case_id=NEW.case_id)) OR (NEW.supplier_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM suppliers WHERE id=NEW.supplier_id AND tenant_id=NEW.tenant_id)) OR (NEW.installation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM installations WHERE id=NEW.installation_id AND tenant_id=NEW.tenant_id)) OR (NEW.verified_by IS NOT NULL AND NOT EXISTS (SELECT 1 FROM users WHERE id=NEW.verified_by AND tenant_id=NEW.tenant_id))) THEN RAISE EXCEPTION 'tenant relationship mismatch'; END IF; RETURN NEW; END $cbeos$;
DROP TRIGGER IF EXISTS trg_facts_tenant_guard ON public.facts;
CREATE TRIGGER trg_facts_tenant_guard BEFORE INSERT OR UPDATE ON public.facts FOR EACH ROW EXECUTE FUNCTION public.cbeos_guard_facts();
CREATE OR REPLACE FUNCTION public.cbeos_guard_evidence() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $cbeos$ BEGIN IF (NOT EXISTS (SELECT 1 FROM cases WHERE id=NEW.case_id AND tenant_id=NEW.tenant_id) OR (NEW.document_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM documents WHERE id=NEW.document_id AND tenant_id=NEW.tenant_id AND case_id=NEW.case_id))) THEN RAISE EXCEPTION 'tenant relationship mismatch'; END IF; RETURN NEW; END $cbeos$;
DROP TRIGGER IF EXISTS trg_evidence_tenant_guard ON public.evidence;
CREATE TRIGGER trg_evidence_tenant_guard BEFORE INSERT OR UPDATE ON public.evidence FOR EACH ROW EXECUTE FUNCTION public.cbeos_guard_evidence();
CREATE OR REPLACE FUNCTION public.cbeos_guard_evidence_requirements() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $cbeos$ BEGIN IF (NOT EXISTS (SELECT 1 FROM cases WHERE id=NEW.case_id AND tenant_id=NEW.tenant_id)) THEN RAISE EXCEPTION 'tenant relationship mismatch'; END IF; RETURN NEW; END $cbeos$;
DROP TRIGGER IF EXISTS trg_evidence_requirements_tenant_guard ON public.evidence_requirements;
CREATE TRIGGER trg_evidence_requirements_tenant_guard BEFORE INSERT OR UPDATE ON public.evidence_requirements FOR EACH ROW EXECUTE FUNCTION public.cbeos_guard_evidence_requirements();
CREATE OR REPLACE FUNCTION public.cbeos_guard_exceptions() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $cbeos$ BEGIN IF (NOT EXISTS (SELECT 1 FROM cases WHERE id=NEW.case_id AND tenant_id=NEW.tenant_id) OR (NEW.reviewer_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM users WHERE id=NEW.reviewer_id AND tenant_id=NEW.tenant_id)) OR (NEW.closed_by IS NOT NULL AND NOT EXISTS (SELECT 1 FROM users WHERE id=NEW.closed_by AND tenant_id=NEW.tenant_id))) THEN RAISE EXCEPTION 'tenant relationship mismatch'; END IF; RETURN NEW; END $cbeos$;
DROP TRIGGER IF EXISTS trg_exceptions_tenant_guard ON public.exceptions;
CREATE TRIGGER trg_exceptions_tenant_guard BEFORE INSERT OR UPDATE ON public.exceptions FOR EACH ROW EXECUTE FUNCTION public.cbeos_guard_exceptions();
CREATE OR REPLACE FUNCTION public.cbeos_guard_supplier_requests() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $cbeos$ BEGIN IF (NOT EXISTS (SELECT 1 FROM cases WHERE id=NEW.case_id AND tenant_id=NEW.tenant_id) OR NOT EXISTS (SELECT 1 FROM suppliers WHERE id=NEW.supplier_id AND tenant_id=NEW.tenant_id) OR (NEW.created_by IS NOT NULL AND NOT EXISTS (SELECT 1 FROM users WHERE id=NEW.created_by AND tenant_id=NEW.tenant_id))) THEN RAISE EXCEPTION 'tenant relationship mismatch'; END IF; RETURN NEW; END $cbeos$;
DROP TRIGGER IF EXISTS trg_supplier_requests_tenant_guard ON public.supplier_requests;
CREATE TRIGGER trg_supplier_requests_tenant_guard BEFORE INSERT OR UPDATE ON public.supplier_requests FOR EACH ROW EXECUTE FUNCTION public.cbeos_guard_supplier_requests();
CREATE OR REPLACE FUNCTION public.cbeos_guard_emissions_data() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $cbeos$ BEGIN IF (NOT EXISTS (SELECT 1 FROM installations WHERE id=NEW.installation_id AND tenant_id=NEW.tenant_id) OR (NEW.reporting_period_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM reporting_periods WHERE id=NEW.reporting_period_id AND tenant_id=NEW.tenant_id)) OR (NEW.source_fact_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM facts WHERE id=NEW.source_fact_id AND tenant_id=NEW.tenant_id))) THEN RAISE EXCEPTION 'tenant relationship mismatch'; END IF; RETURN NEW; END $cbeos$;
DROP TRIGGER IF EXISTS trg_emissions_data_tenant_guard ON public.emissions_data;
CREATE TRIGGER trg_emissions_data_tenant_guard BEFORE INSERT OR UPDATE ON public.emissions_data FOR EACH ROW EXECUTE FUNCTION public.cbeos_guard_emissions_data();
CREATE OR REPLACE FUNCTION public.cbeos_guard_calculation_runs() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $cbeos$ BEGIN IF (NOT EXISTS (SELECT 1 FROM cases WHERE id=NEW.case_id AND tenant_id=NEW.tenant_id) OR (NEW.import_line_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM import_lines WHERE id=NEW.import_line_id AND tenant_id=NEW.tenant_id AND case_id=NEW.case_id)) OR (NEW.created_by IS NOT NULL AND NOT EXISTS (SELECT 1 FROM users WHERE id=NEW.created_by AND tenant_id=NEW.tenant_id))) THEN RAISE EXCEPTION 'tenant relationship mismatch'; END IF; RETURN NEW; END $cbeos$;
DROP TRIGGER IF EXISTS trg_calculation_runs_tenant_guard ON public.calculation_runs;
CREATE TRIGGER trg_calculation_runs_tenant_guard BEFORE INSERT OR UPDATE ON public.calculation_runs FOR EACH ROW EXECUTE FUNCTION public.cbeos_guard_calculation_runs();
CREATE OR REPLACE FUNCTION public.cbeos_guard_verification_records() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $cbeos$ BEGIN IF (NOT EXISTS (SELECT 1 FROM installations WHERE id=NEW.installation_id AND tenant_id=NEW.tenant_id) OR (NEW.reporting_period_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM reporting_periods WHERE id=NEW.reporting_period_id AND tenant_id=NEW.tenant_id))) THEN RAISE EXCEPTION 'tenant relationship mismatch'; END IF; RETURN NEW; END $cbeos$;
DROP TRIGGER IF EXISTS trg_verification_records_tenant_guard ON public.verification_records;
CREATE TRIGGER trg_verification_records_tenant_guard BEFORE INSERT OR UPDATE ON public.verification_records FOR EACH ROW EXECUTE FUNCTION public.cbeos_guard_verification_records();
CREATE OR REPLACE FUNCTION public.cbeos_guard_declaration_packages() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $cbeos$ BEGIN IF (NOT EXISTS (SELECT 1 FROM cases WHERE id=NEW.case_id AND tenant_id=NEW.tenant_id) OR (NEW.generated_by IS NOT NULL AND NOT EXISTS (SELECT 1 FROM users WHERE id=NEW.generated_by AND tenant_id=NEW.tenant_id))) THEN RAISE EXCEPTION 'tenant relationship mismatch'; END IF; RETURN NEW; END $cbeos$;
DROP TRIGGER IF EXISTS trg_declaration_packages_tenant_guard ON public.declaration_packages;
CREATE TRIGGER trg_declaration_packages_tenant_guard BEFORE INSERT OR UPDATE ON public.declaration_packages FOR EACH ROW EXECUTE FUNCTION public.cbeos_guard_declaration_packages();
CREATE OR REPLACE FUNCTION public.cbeos_guard_approvals() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $cbeos$ BEGIN IF (NOT EXISTS (SELECT 1 FROM cases WHERE id=NEW.case_id AND tenant_id=NEW.tenant_id) OR (NEW.actor_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM users WHERE id=NEW.actor_id AND tenant_id=NEW.tenant_id))) THEN RAISE EXCEPTION 'tenant relationship mismatch'; END IF; RETURN NEW; END $cbeos$;
DROP TRIGGER IF EXISTS trg_approvals_tenant_guard ON public.approvals;
CREATE TRIGGER trg_approvals_tenant_guard BEFORE INSERT OR UPDATE ON public.approvals FOR EACH ROW EXECUTE FUNCTION public.cbeos_guard_approvals();
CREATE OR REPLACE FUNCTION public.cbeos_guard_audit() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $cbeos$ BEGIN IF ((NEW.tenant_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM tenants WHERE id=NEW.tenant_id)) OR (NEW.case_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM cases WHERE id=NEW.case_id AND tenant_id=NEW.tenant_id)) OR (NEW.actor_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM users WHERE id=NEW.actor_id AND tenant_id=NEW.tenant_id))) THEN RAISE EXCEPTION 'tenant relationship mismatch'; END IF; RETURN NEW; END $cbeos$;
DROP TRIGGER IF EXISTS trg_audit_tenant_guard ON public.audit;
CREATE TRIGGER trg_audit_tenant_guard BEFORE INSERT OR UPDATE ON public.audit FOR EACH ROW EXECUTE FUNCTION public.cbeos_guard_audit();
CREATE OR REPLACE FUNCTION public.cbeos_guard_agent_run_case() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $cbeos$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.cases WHERE id=NEW.case_id AND tenant_id=NEW.tenant_id) THEN RAISE EXCEPTION 'agent run tenant/case mismatch'; END IF; RETURN NEW; END $cbeos$;
DROP TRIGGER IF EXISTS agent_runs_tenant_insert ON public.agent_runs;
DROP TRIGGER IF EXISTS agent_runs_tenant_update ON public.agent_runs;
CREATE TRIGGER agent_runs_tenant_insert BEFORE INSERT ON public.agent_runs FOR EACH ROW EXECUTE FUNCTION public.cbeos_guard_agent_run_case();
CREATE TRIGGER agent_runs_tenant_update BEFORE UPDATE OF tenant_id,case_id ON public.agent_runs FOR EACH ROW EXECUTE FUNCTION public.cbeos_guard_agent_run_case();
